const hQ12_BatchUpsert = `-- name: HQ12_BatchUpsert :execrows
INSERT INTO postgres_air.flight_status_update (flight_id, status, actual_departure, actual_arrival, update_ts, version)
VALUES ($1, $2, $3, $4, $5, $6)
ON CONFLICT (flight_id) DO UPDATE SET
    status = EXCLUDED.status,
    actual_departure = EXCLUDED.actual_departure,
    actual_arrival = EXCLUDED.actual_arrival,
    update_ts = EXCLUDED.update_ts,
    version = postgres_air.flight_status_update.version + 1
`

type HQ12_BatchUpsertParams struct {
	FlightID        int32
	Status          string
	ActualDeparture pgtype.Timestamptz
	ActualArrival   pgtype.Timestamptz
	UpdateTs        pgtype.Timestamptz
	Version         int32
}

func (q *Queries) HQ12_BatchUpsert(ctx context.Context, arg HQ12_BatchUpsertParams) (int64, error) {
	result, err := q.db.Exec(ctx, hQ12_BatchUpsert,
		arg.FlightID,
		arg.Status,
		arg.ActualDeparture,
		arg.ActualArrival,
		arg.UpdateTs,
		arg.Version,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

